import { useDeferredValue, useMemo, useState, type ComponentType } from 'react'
import { BarChart3, ChevronLeft, ChevronRight, Download, FileSpreadsheet, Filter, Fuel, Printer, Search, TrendingUp } from 'lucide-react'
import { Link, type LinkProps } from 'react-router'
import { useExportGarageReport, useGarageAreas, useGarageReport, useGarageTanks, useGarageVehicles } from '@features/central-garage/hooks'
import type { GarageMovementType, GarageReportFilter, GarageReportMode, GarageReportResult } from '@features/central-garage/reports'
import type { GarageFuelType, GarageVehicle } from '@features/central-garage/types'
import { garageUnitLabel } from '@features/central-garage/fuel-units'
import { LoadingSpinner } from '@components/feedback/LoadingSpinner'
import { ExecPageHeader } from '@components/executive/ExecPageHeader'
import { parentSectorLabel, parentCodesOf } from '@features/sectors'

const fuelLabels:Record<GarageFuelType,string>={gas_oil:'الكاز',hydraulic:'الهيدروليك',grease:'الدهن',c_oil:'C-Oil'}
const movementLabels:Record<GarageMovementType,string>={stock_in:'إضافة مخزون',vehicle_fill:'تعبئة آلية',approved_reset:'تصفير معتمد'}
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Baghdad',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const monthAgo=()=>{const d=new Date(`${today()}T12:00:00+03:00`);d.setDate(d.getDate()-29);return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Baghdad',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
const num=(value:number)=>new Intl.NumberFormat('ar-IQ-u-nu-latn',{maximumFractionDigits:3}).format(value)
const arDate=(value:string)=>new Intl.DateTimeFormat('ar-IQ-u-nu-latn',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Baghdad'}).format(new Date(value))
const inputClass='h-11 w-full rounded-xl border border-slate-300 bg-white px-3 text-sm outline-none focus:border-cyan-600 focus:ring-2 focus:ring-cyan-100'

/**
 * 00400: الصفحة صارت قابلة لإعادة الاستخدام في بوابة أخرى (مدير غرفة العمليات).
 *  · title/subtitle: تعريض العنوان فقط (الافتراضي = الكراج المركزي، لا تغيير سلوك).
 *  · vehicleHrefBase: أساس رابط بطاقة الآلية؛ null ⇒ بلا رابط (عندما لا تملك البوابة المستقبِلة صفحة آلية).
 */
export interface GarageReportsPageProps { title?: string; subtitle?: string; vehicleHrefBase?: string | null }
export default function GarageReportsPage({ title = 'تقارير الكراج المركزي', subtitle = 'التحليل والتصدير — تقارير الآليات والخزانات والمواد والحركات وفق الفترة والموقع المحددين', vehicleHrefBase = '/central-garage/vehicles-database' }: GarageReportsPageProps = {}){
  const[filter,setFilter]=useState<GarageReportFilter>({from:monthAgo(),to:today(),page:1,pageSize:50});const[reportMode,setReportMode]=useState<GarageReportMode>('all');const[vehicleSearch,setVehicleSearch]=useState('');const deferred=useDeferredValue(vehicleSearch);const[selectedVehicles,setSelectedVehicles]=useState<GarageVehicle[]>([])
  const areas=useGarageAreas();const tanks=useGarageTanks(filter.fuelType);const vehicles=useGarageVehicles({search:deferred,pageSize:20});const report=useGarageReport(filter);const exporter=useExportGarageReport();const data=report.data
  const maxType=Math.max(1,...(data?.byType.map(item=>item.quantity)??[]));const pages=Math.max(1,Math.ceil((data?.totalCount??0)/(filter.pageSize??50)))
  const exportFilter=useMemo(()=>({from:filter.from,to:filter.to,sectorId:filter.sectorId,fuelType:filter.fuelType,tankId:filter.tankId,vehicleIds:filter.vehicleIds,movementType:filter.movementType}),[filter])
  const update=<K extends keyof GarageReportFilter>(key:K,value:GarageReportFilter[K])=>setFilter(old=>({...old,[key]:value,page:1}))
  const changeMode=(mode:GarageReportMode)=>{setReportMode(mode);setSelectedVehicles([]);setVehicleSearch('');setFilter(old=>({...old,vehicleId:undefined,vehicleIds:mode==='all'?undefined:[],page:1}))}
  const chooseVehicle=(vehicle:GarageVehicle)=>{const next=reportMode==='single_vehicle'?[vehicle]:selectedVehicles.some(item=>item.id===vehicle.id)?selectedVehicles:[...selectedVehicles,vehicle].slice(0,50);setSelectedVehicles(next);setVehicleSearch('');update('vehicleIds',next.map(item=>item.id))}
  const removeVehicle=(id:string)=>{const next=selectedVehicles.filter(item=>item.id!==id);setSelectedVehicles(next);update('vehicleIds',next.map(item=>item.id))}
  return <section className="space-y-5" dir="rtl" data-testid="garage-reports-page">
    <ExecPageHeader icon="bar-chart" title={title} subtitle={subtitle}
      stats={data ? [{ label: 'الحركات', value: num(data.totalCount), tone: 'gold' }, { label: 'الفترة', value: <span dir="ltr" className="text-sm">{data.from} → {data.to}</span> }] : undefined}
      actions={<div className="flex flex-wrap gap-2 print:hidden"><button disabled={exporter.isPending} onClick={()=>{const printWindow=window.open('','_blank','width=1200,height=850');if(printWindow){printWindow.document.write('<div dir="rtl" style="font-family:Tahoma;padding:40px;text-align:center">جارٍ إعداد التقرير الكامل…</div>')}exporter.mutate({filter:exportFilter,format:'print',printWindow})}} className="inline-flex h-9 items-center gap-1 rounded-xl bg-white px-3 text-xs font-black text-[#0b3d6b] shadow disabled:opacity-50"><Printer size={16}/>تقرير طباعة مصمم</button><button disabled={exporter.isPending} title="صيغة بيانات خام للتكامل مع الأنظمة" onClick={()=>exporter.mutate({filter:exportFilter,format:'csv'})} className="inline-flex h-9 items-center gap-1 rounded-xl bg-white/10 px-3 text-xs font-black text-white ring-1 ring-white/25 disabled:opacity-50"><Download size={16}/>CSV بيانات خام</button><button disabled={exporter.isPending} onClick={()=>exporter.mutate({filter:exportFilter,format:'xlsx'})} className="inline-flex h-10 items-center gap-2 rounded-xl bg-white px-4 text-xs font-black text-emerald-900 disabled:opacity-50"><FileSpreadsheet size={16}/>{exporter.isPending?'جارٍ التصدير…':'Excel كامل'}</button></div>} />

    <div className="rounded-3xl border bg-white p-4 shadow-sm print:hidden"><div className="mb-3 flex items-center gap-2 text-sm font-black text-slate-800"><Filter size={17}/>تخصيص التقرير</div><div className="mb-5 grid gap-2 sm:grid-cols-3" role="radiogroup" aria-label="نوع التقرير">{([{id:'all',title:'تقرير شامل',hint:'كل الآليات والمخزون'},{id:'single_vehicle',title:'تقرير آلية واحدة',hint:'سجل آلية محددة خلال فترة'},{id:'selected_vehicles',title:'تقرير آليات محددة',hint:'اختر عدة آليات للمقارنة'}] as Array<{id:GarageReportMode;title:string;hint:string}>).map(option=><button key={option.id} type="button" role="radio" aria-checked={reportMode===option.id} data-testid={`report-mode-${option.id}`} onClick={()=>changeMode(option.id)} className={`rounded-2xl border p-3 text-right transition ${reportMode===option.id?'border-cyan-600 bg-cyan-50 ring-2 ring-cyan-100':'border-slate-200 hover:border-cyan-300'}`}><b className="block text-sm text-slate-900">{option.title}</b><small className="mt-1 block text-slate-500">{option.hint}</small></button>)}</div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><label className="text-xs font-bold text-slate-600">من<input aria-label="من تاريخ التقرير" type="date" max={filter.to} value={filter.from??''} onChange={e=>update('from',e.target.value)} className={`mt-1 ${inputClass}`}/></label><label className="text-xs font-bold text-slate-600">إلى<input aria-label="إلى تاريخ التقرير" type="date" min={filter.from} max={today()} value={filter.to??''} onChange={e=>update('to',e.target.value)} className={`mt-1 ${inputClass}`}/></label><label className="text-xs font-bold text-slate-600">القاطع والمنطقة<select data-testid="report-area" value={filter.sectorId??''} onChange={e=>update('sectorId',e.target.value?Number(e.target.value):undefined)} className={`mt-1 ${inputClass}`}><option value="">الكل</option>{parentCodesOf(areas.data??[]).map(parent=><optgroup key={parent} label={parentSectorLabel(parent)}>{(areas.data??[]).filter(a=>a.parentSector===parent).map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</optgroup>)}</select></label><label className="text-xs font-bold text-slate-600">نوع المادة<select data-testid="report-fuel" value={filter.fuelType??''} onChange={e=>{const value=(e.target.value||undefined) as GarageFuelType|undefined;setFilter(old=>({...old,fuelType:value,tankId:undefined,page:1}))}} className={`mt-1 ${inputClass}`}><option value="">كل المواد</option>{Object.entries(fuelLabels).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label><label className="text-xs font-bold text-slate-600">الخزان<select data-testid="report-tank" value={filter.tankId??''} onChange={e=>update('tankId',e.target.value||undefined)} className={`mt-1 ${inputClass}`}><option value="">كل الخزانات</option>{tanks.data?.map(tank=><option key={tank.id} value={tank.id}>{tank.tankName} · {fuelLabels[tank.fuelType]}</option>)}</select></label><label className="text-xs font-bold text-slate-600">نوع الحركة<select data-testid="report-movement" value={filter.movementType??''} onChange={e=>update('movementType',(e.target.value||undefined) as GarageMovementType|undefined)} className={`mt-1 ${inputClass}`}><option value="">كل الحركات</option>{Object.entries(movementLabels).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label>{reportMode!=='all'&&<div className="relative sm:col-span-2"><div className="flex items-center justify-between"><label className="text-xs font-bold text-slate-600">{reportMode==='single_vehicle'?'الآلية المطلوبة':'الآليات المطلوبة'}</label><span className="text-[11px] font-bold text-cyan-700">{selectedVehicles.length}{reportMode==='selected_vehicles'?' / 50':' / 1'}</span></div><div className="relative mt-1"><Search className="absolute right-3 top-3 text-slate-400" size={17}/><input data-testid="report-vehicle-search" value={vehicleSearch} onChange={e=>setVehicleSearch(e.target.value)} className={`${inputClass} pr-10`} placeholder="ابحث بـ DB أو اسم الآلية أو السائق أو اللوحة"/></div>{vehicleSearch.trim()&&<div className="absolute z-20 mt-1 max-h-60 w-full overflow-y-auto rounded-xl border bg-white p-1 shadow-xl">{vehicles.data?.rows.filter(v=>!selectedVehicles.some(item=>item.id===v.id)).map(v=><button key={v.id} data-testid={`report-vehicle-${v.id}`} type="button" onClick={()=>chooseVehicle(v)} className="block w-full rounded-lg px-3 py-2 text-right text-xs hover:bg-cyan-50"><b>{v.vehicleName}</b> · DB {v.dbNumber}<small className="mt-1 block text-slate-400">{v.driverName} · {v.areaName}</small></button>)}{!vehicles.data?.rows.filter(v=>!selectedVehicles.some(item=>item.id===v.id)).length&&<p className="p-3 text-xs text-slate-400">لا توجد نتائج أخرى</p>}</div>}<div className="mt-2 flex flex-wrap gap-2">{selectedVehicles.map(v=><span key={v.id} data-testid={`selected-report-vehicle-${v.id}`} className="inline-flex items-center gap-2 rounded-xl border border-cyan-200 bg-cyan-50 px-3 py-2 text-xs font-bold text-cyan-900"><span>{v.vehicleName} · DB {v.dbNumber}</span><button type="button" aria-label={`إزالة ${v.vehicleName}`} onClick={()=>removeVehicle(v.id)} className="text-red-600">×</button></span>)}</div>{!selectedVehicles.length&&<p className="mt-2 rounded-xl bg-amber-50 p-2 text-[11px] font-bold text-amber-800">اختر {reportMode==='single_vehicle'?'آلية واحدة':'آلية واحدة أو أكثر'} لإعداد التقرير المخصص.</p>}</div>}</div></div>

    {report.isLoading?<div className="rounded-3xl border bg-white p-12"><LoadingSpinner label="جارٍ إعداد التقرير…"/></div>:report.isError||!data?<div role="alert" className="rounded-3xl border border-red-200 bg-red-50 p-6 text-center font-bold text-red-700">تعذر إعداد التقرير. تحقق من الفترة والفلاتر.</div>:<>
      {reportMode!=='all'&&<article className="rounded-3xl border border-cyan-200 bg-gradient-to-l from-cyan-50 to-white p-5"><p className="text-xs font-bold text-cyan-700">{reportMode==='single_vehicle'?'تقرير آلية مخصص':'تقرير مجموعة آليات'}</p><h2 className="mt-1 text-xl font-black text-slate-900">{data.selectedVehicles?.length?data.selectedVehicles.map(v=>`${v.vehicleName} · DB ${v.dbNumber}`).join('، '):'اختر الآلية المطلوبة أعلاه'}</h2>{data.selectedVehicles?.length===1&&<p className="mt-2 text-xs text-slate-600">السائق: {data.selectedVehicles[0]?.driverName} · اللوحة: {data.selectedVehicles[0]?.plateNumber} · المنطقة: {data.selectedVehicles[0]?.areaName??'—'}</p>}<p className="mt-2 text-xs text-slate-500">الفترة من {filter.from} إلى {filter.to}</p></article>}
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Summary title="عدد الحركات" value={data.totalCount} tone="text-slate-800" suffix="حركة"/>{(data.byUnit??[]).map(item=><Summary key={item.unit} title={`رصيد حركة ${garageUnitLabel(item.unit)}`} value={item.consumption} tone="text-amber-700" suffix={`استهلاك · إضافات ${num(item.stockIn)} · تصفير ${num(item.reset)}`}/>)}</div>
      <ReportOverview data={data}/>
      <div className="grid gap-5 xl:grid-cols-2"><article className="rounded-3xl border bg-white p-5 shadow-sm"><h2 className="flex items-center gap-2 font-black"><TrendingUp size={18} className="text-cyan-700"/>الاستهلاك حسب المادة</h2><div className="mt-5 space-y-3">{data.byType.map(item=><div key={`${item.fuelType}-${item.unit}`}><div className="mb-1 flex justify-between text-xs"><b>{fuelLabels[item.fuelType]}</b><span>{num(item.quantity)} {garageUnitLabel(item.unit)}</span></div><div className="h-3 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-cyan-600" style={{width:data.byUnit.length===1?`${item.quantity/maxType*100}%`:'100%'}}/></div></div>)}{!data.byType.length&&<p className="py-6 text-center text-sm text-slate-400">لا توجد بيانات</p>}</div></article><article className="rounded-3xl border bg-white p-5 shadow-sm"><h2 className="flex items-center gap-2 font-black"><Fuel size={18} className="text-amber-700"/>ملخص الخزانات</h2><div className="mt-4 max-h-64 space-y-2 overflow-y-auto">{data.byTank.map(tank=><div key={tank.tankId} className="rounded-2xl bg-slate-50 p-3 text-xs"><div className="flex justify-between"><b>{tank.tankName} · {fuelLabels[tank.fuelType]}</b><span className="text-amber-700">استهلاك {num(tank.consumption)} {garageUnitLabel(tank.unit)}</span></div><p className="mt-1 text-emerald-700">إضافات {num(tank.stockIn)} {garageUnitLabel(tank.unit)}</p></div>)}</div></article></div>
      <article className="rounded-3xl border bg-white p-5 shadow-sm"><h2 className="font-black">استهلاك الآليات</h2><div className="mt-4 grid gap-2 md:grid-cols-2 xl:grid-cols-3">{data.byVehicle.slice(0,12).map((vehicle,index)=>{const Row=vehicleHrefBase?Link:'div' as unknown as ComponentType<LinkProps>, rowProps=vehicleHrefBase?{to:`${vehicleHrefBase}/${vehicle.vehicleId}`}:{};return <Row key={`${vehicle.vehicleId}-${vehicle.unit}`} {...(rowProps as LinkProps)} className="flex items-center justify-between rounded-2xl border p-3 text-xs hover:border-cyan-300"><span><b className="ml-2 text-cyan-700">#{index+1}</b>{vehicle.vehicleName}<small className="mr-2 text-slate-400">DB {vehicle.dbNumber}</small></span><b className="text-amber-700">{num(vehicle.quantity)} {garageUnitLabel(vehicle.unit)}</b></Row>})}{!data.byVehicle.length&&<p className="py-5 text-sm text-slate-400">لا توجد تعبئات آليات ضمن التقرير.</p>}</div></article>
      <article className="overflow-hidden rounded-3xl border bg-white shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3 border-b p-5"><div><h2 className="font-black">سجل الحركات التفصيلي</h2><p className="mt-1 text-xs text-slate-400">{data.from} — {data.to}</p></div><b className="rounded-full bg-cyan-50 px-3 py-1 text-xs text-cyan-800">{num(data.totalCount)} حركة</b></div><div className="overflow-x-auto"><table className="w-full min-w-[1100px] text-right text-xs"><thead className="bg-slate-900 text-white"><tr>{['الوقت','الحركة','المادة والخزان','الآلية والموقع','الكمية','قبل / بعد','الموعد التالي','المنفذ','الملاحظات'].map(title=><th key={title} className="p-3">{title}</th>)}</tr></thead><tbody className="divide-y">{data.rows.map(row=><tr key={row.id} className="hover:bg-slate-50"><td className="whitespace-nowrap p-3">{arDate(row.createdAt)}</td><td className="p-3 font-bold">{movementLabels[row.movementType]}</td><td className="p-3"><b>{fuelLabels[row.fuelType]}</b><small className="block text-slate-400">{row.tankName}</small></td><td className="p-3">{row.vehicleName?<><b>{row.vehicleName}</b><small className="block text-slate-400">DB {row.dbNumber} · {row.areaName}</small></>:'—'}</td><td className={`p-3 font-black ${row.quantity>0?'text-emerald-700':'text-red-700'}`}>{row.quantity>0?'+':''}{num(row.quantity)} {garageUnitLabel(row.unit)}</td><td className="p-3">{num(row.quantityBefore)} ← {num(row.quantityAfter)} {garageUnitLabel(row.unit)}</td><td className="p-3">{row.fuelType==='gas_oil'?'لا ينطبق':(row.nextRefillDate??'—')}</td><td className="max-w-36 truncate p-3" title={row.actorId}>{row.actorName}</td><td className="max-w-52 p-3 text-slate-500">{row.notes??'—'}</td></tr>)}{!data.rows.length&&<tr><td colSpan={9} className="p-10 text-center text-slate-400">لا توجد حركات مطابقة.</td></tr>}</tbody></table></div></article>
      {data.totalCount>(filter.pageSize??50)&&<nav className="flex items-center justify-center gap-3 print:hidden" aria-label="صفحات التقرير"><button aria-label="الصفحة السابقة" disabled={(filter.page??1)===1} onClick={()=>setFilter(old=>({...old,page:(old.page??1)-1}))} className="rounded-xl border bg-white p-2 disabled:opacity-40"><ChevronRight/></button><span className="text-sm font-bold">{filter.page??1} من {pages}</span><button aria-label="الصفحة التالية" disabled={(filter.page??1)>=pages} onClick={()=>setFilter(old=>({...old,page:(old.page??1)+1}))} className="rounded-xl border bg-white p-2 disabled:opacity-40"><ChevronLeft/></button></nav>}
    </>}
  </section>
}
function ReportOverview({data}:{data:GarageReportResult}){const maxVehicle=Math.max(1,...data.byVehicle.map(item=>item.quantity));return <section className="grid gap-5 xl:grid-cols-2" aria-label="الرسوم التحليلية"><article className="rounded-3xl border bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="font-black">توازن الحركات حسب الوحدة</h2><p className="mt-1 text-xs text-slate-500">الإضافات والاستهلاك والتصفير دون خلط الوحدات</p></div><BarChart3 className="text-emerald-700"/></div><div className="mt-5 space-y-5">{data.byUnit.map(item=>{const total=Math.max(1,item.stockIn+item.consumption+item.reset);return <div key={item.unit}><div className="mb-2 flex justify-between text-xs"><b>{garageUnitLabel(item.unit)}</b><span>إضافة {num(item.stockIn)} · استهلاك {num(item.consumption)} · تصفير {num(item.reset)}</span></div><div className="flex h-4 overflow-hidden rounded-full bg-slate-100" title={`إضافة ${item.stockIn}، استهلاك ${item.consumption}، تصفير ${item.reset}`}><i className="bg-emerald-500" style={{width:`${item.stockIn/total*100}%`}}/><i className="bg-amber-500" style={{width:`${item.consumption/total*100}%`}}/><i className="bg-red-500" style={{width:`${item.reset/total*100}%`}}/></div></div>})}{!data.byUnit.length&&<p className="py-8 text-center text-sm text-slate-400">لا توجد حركات ضمن الفترة</p>}</div><div className="mt-4 flex flex-wrap gap-4 border-t pt-3 text-[11px]"><span><i className="ml-1 inline-block size-2 rounded-full bg-emerald-500"/>إضافة</span><span><i className="ml-1 inline-block size-2 rounded-full bg-amber-500"/>استهلاك</span><span><i className="ml-1 inline-block size-2 rounded-full bg-red-500"/>تصفير</span></div></article><article className="rounded-3xl border bg-white p-5 shadow-sm"><h2 className="font-black">أعلى الآليات استهلاكاً</h2><p className="mt-1 text-xs text-slate-500">يعرض كل استهلاك بوحدته الفعلية</p><div className="mt-5 space-y-3">{data.byVehicle.slice(0,6).map(item=><div key={`${item.vehicleId}-${item.unit}`}><div className="mb-1 flex justify-between text-xs"><span><b>{item.vehicleName}</b> · DB {item.dbNumber}</span><b className="text-amber-700">{num(item.quantity)} {garageUnitLabel(item.unit)}</b></div><div className="h-2.5 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-gradient-to-l from-cyan-600 to-blue-700" style={{width:`${item.quantity/maxVehicle*100}%`}}/></div></div>)}{!data.byVehicle.length&&<p className="py-8 text-center text-sm text-slate-400">لا توجد تعبئات آليات</p>}</div></article></section>}
function Summary({title,value,tone,suffix}:{title:string;value:number;tone:string;suffix?:string}){return <article className="rounded-3xl border bg-white p-5 shadow-sm"><p className="text-xs font-bold text-slate-500">{title}</p><b className={`mt-2 block text-3xl ${tone}`}>{num(value)}</b>{suffix&&<p className="mt-1 text-[11px] text-slate-400">{suffix}</p>}</article>}
